    max_results = self._get_int_param("maxResults")
    next_token = self._get_param("nextToken")
    channels = self.medialive_backend.list_channels(max_results=max_results, next_token=next_token)

    # Calculate the next token for pagination
    new_next_token = None
    if max_results is not None and channels:
        start_idx = 0
        if next_token:
            try:
                start_idx = int(next_token)
            except ValueError:
                start_idx = 0

        # If we have more items, set the next token
        if len(channels) == max_results and start_idx + max_results < len(self.medialive_backend._channels):
            new_next_token = str(start_idx + max_results)

    return json.dumps(dict(channels=channels, nextToken=new_next_token))

